s=s.replace('''                String(format: "%.1f", e.gainDB).draw(at: NSPoint(x: centerX + 13, y: knobY - 5), withAttributes: gattrs)''','''                let gainText = String(format: "%.1f dB", e.gainDB)\n                let gainSize = gainText.size(withAttributes: gattrs)\n                gainText.draw(at: NSPoint(x: centerX - gainSize.width / 2, y: knobY - 4), withAttributes: gattrs)''',1)
