s=s.replace('''    func applicationWillTerminate(_ notification: Notification) {\n        if let monitor = keyMonitor { NSEvent.removeMonitor(monitor) }''','''    func applicationWillTerminate(_ notification: Notification) {\n        saveCurrentSession()\n        if let monitor = keyMonitor { NSEvent.removeMonitor(monitor) }''',1)

